<!DOCTYPE html>
<html>
<head>
  <title>Falling Sand Cellular Automata</title>
  <style>
    body {
      background-color: #1e1e1e;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      margin: 0;
      font-family: sans-serif;
    }

    #controls {
      display: flex;
      gap: 20px;
      margin-bottom: 20px;
    }

    .button {
      background-color: #3e3e3e;
      color: white;
      padding: 10px 15px;
      border: none;
      cursor: pointer;
      font-size: 16px;
      border-radius: 5px;
    }

    .button:hover {
      background-color: #5e5e5e;
    }

    #canvas {
      border: 1px solid #555;
      background-color: #222;
      cursor: crosshair;
    }
  </style>
</head>
<body>
  <div id="controls">
    <button class="button" onclick="sim.set(0, 0, 'sand')">#mat-sand</button>
    <button class="button" onclick="sim.set(0, 0, 'water')">#mat-water</button>
    <button class="button" onclick="sim.set(0, 0, 'wall')">#mat-wall</button>
    <button class="button" onclick="sim.set(0, 0, 'acid')">#mat-acid</button>
    <button class="button" onclick="sim.set(0, 0, 'empty')">#mat-empty</button>
    <button class="button" onclick="sim.clear()">Clear</button>
  </div>

  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const w = 80;
    const h = 80;
    let grid = [];
    let isDragging = false;
    let dragX = null;
    let dragY = null;

    function initGrid() {
      grid = Array(h).fill(null).map(() => Array(w).fill('empty'));
    }

    function drawGrid() {
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const material = grid[y][x];
          const colorMap = {
            'empty': '#222',
            'sand': '#a5d6a7',
            'water': '#87CEEB',
            'wall': '#808080',
            'acid': '#ff4500'
          };

          ctx.fillStyle = colorMap[material];
          ctx.fillRect(x * 16, y * 16, 16, 16);
        }
      }
    }


    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      dragX = e.clientX - canvas.offsetLeft;
      dragY = e.clientY - canvas.offsetTop;
    });

    canvas.addEventListener('mouseup', () => {
      isDragging = false;
      dragX = null;
      dragY = null;
    });

    canvas.addEventListener('mouseleave', () => {
      isDragging = false;
      dragX = null;
      dragY = null;
    });


    canvas.addEventListener('mousemove', (e) => {
      if (!isDragging || dragX === null || dragY === null) return;

      const x = Math.max(0, Math.min(w - 1, e.clientX - dragX));
      const y = Math.max(0, Math.min(h - 1, e.clientY - dragY));

      sim.set(x, y, 'empty');
    });


    function sim_tick(n) {
      for (let i = 0; i < n; i++) {
        // Process bottom-row-up
        for (let y = h - 1; y >= 0; y--) {
          let neighbors = [];
          if (y > 0) neighbors.push(grid[y - 1][Math.max(0, Math.min(w - 1, grid[y][Math.max(0, Math.min(w-1, grid[y][0]))]) ])); // Up
          if (y < h - 1) neighbors.push(grid[y + 1][Math.max(0, Math.min(w - 1, grid[y][Math.max(0, Math.min(w-1, grid[y][0]))]) ])); // Down
          if (Math.max(0, Math.min(w - 1, grid[y][0])) > 0) neighbors.push(grid[y][Math.max(0, Math.min(w - 1, grid[y][0])) - 1]); // Left
          if (Math.max(0, Math.min(w - 1, grid[y][0])) < w - 1) neighbors.push(grid[y][Math.min(w - 1, grid[y][0]) + 1]); // Right


          let current = grid[y][0];
          if (current === 'sand') {
            let moved = false;
            for (const neighbor of neighbors) {
              if (neighbor === 'empty') {
                grid[y][0] = 'empty';
                moved = true;
                break;
              }
            }
            if (!moved) {
              grid[y][0] = 'empty';
            }

          } else if (current === 'water') {
            let moved = false;
            for (const neighbor of neighbors) {
              if (neighbor === 'empty') {
                grid[y][0] = 'empty';
                moved = true;
                break;
              }
            }

            if (!moved) {
               let dir = Math.floor(Math.random() * 2); // 0=left, 1=right
               if (dir === 0 && Math.max(0, Math.min(w - 1, grid[y][0] - 1)) >= 0) {
                 grid[y][0] = grid[y][Math.max(0, Math.min(w-1, grid[y][0]-1)]];
                 grid[y][Math.max(0, Math.min(w-1, grid[y][0]-1))] = 'empty';
               } else if (dir === 1 && Math.min(w - 1, grid[y][0] + 1) < w){
                 grid[y][0] = grid[y][Math.min(w-1, grid[y][0]+1)];
                 grid[y][Math.min(w-1, grid[y][0]+1)] = 'empty';
               }

            }
          } else if (current === 'acid') {
            let moved = false;
            for (const neighbor of neighbors) {
              if (neighbor === 'sand' || neighbor === 'wall') {
                grid[y][0] = 'empty';
                moved = true;
                break;
              } else if (neighbor !== 'acid') { // Don't dissolve acid
                grid[y][0] = neighbor;
                grid[y][Math.max(0, Math.min(w - 1, neighbor)] ) = 'empty';
                moved = true;
                break;
              }
            }

            if (!moved) {
                let dir = Math.floor(Math.random() * 2); // 0=left, 1=right
                if (dir === 0 && Math.max(0, Math.min(w - 1, grid[y][0] - 1)) >= 0) {
                  grid[y][0] = grid[y][Math.max(0, Math.min(w-1, grid[y][0]-1)]];
                  grid[y][Math.max(0, Math.min(w-1, grid[y][0]-1))] = 'empty';
                } else if (dir === 1 && Math.min(w - 1, grid[y][0] + 1) < w){
                  grid[y][0] = grid[y][Math.min(w-1, grid[y][0]+1)];
                  grid[y][Math.min(w-1, grid[y][0]+1)] = 'empty';
                }

            }
          } else {
            grid[y][0] = 'empty'; // Walls and empty cells don't move
          }
        }
      }
    }

    sim.w = w;
    sim.h = h;
    sim.tick = sim_tick;
    sim.get = (x, y) => grid[y][x];
    sim.set = (x, y, material) => grid[y][x] = material;
    sim.clear = () => {
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          grid[y][x] = 'empty';
        }
      }
    };

    initGrid();
    drawGrid();

  </script>
</body>
</html>
